mapper.select:
        SELECT EPISODE FROM MEETING_SCHEDULE
		WHERE EPISODE = #{episode}
		AND 
		HEADCOUNT/2 > (
		SELECT COUNT(*) FROM PARTICIPANT_USER A
		WHERE A.EPISODE = #{episode}
		AND A.SEX = (SELECT SEX FROM USER_TABLE WHERE USER_ID = #{userId})
		)

        SELECT USER_ID FROM PARTICIPANT_USER 
		WHERE USER_ID = #{userId}
		AND EPISODE BETWEEN DATE_ADD(#{LocalDateTimeEpisode}, INTERVAL -12 HOUR) AND DATE_ADD(#{LocalDateTimeEpisode}, INTERVAL -1 HOUR)

    SELECT COUNT(*) FROM PARTICIPANT_USER
	WHERE EPISODE = #{LocalDateTimeEpisode}
	AND USER_ID IN (
	SELECT USER_ID FROM PARTICIPANT_USER 
	WHERE EPISODE IN 
	(SELECT EPISODE FROM PARTICIPANT_USER WHERE USER_ID = #{userId} AND EPISODE < #{LocalDateTimeEpisode})
	and USER_ID <> #{userId}
	)

        SELECT COUNT(*) 
        FROM MATCHING
		WHERE USER_ID = #{userId}
		AND EPISODE = #{episode}
